```python
import asyncio

from fastmcp import FastMCP, Client

server = FastMCP("ConfigServer")


@server.resource("data://config")
def get_config() -> dict:
    return {"debug": True, "version": "1.0.0"}


async def main() -> None:
    client = Client(server)  # in-memory transport, no subprocess/network

    async with client:
        contents = await client.read_resource("data://config")
        for item in contents:
            if hasattr(item, "text"):
                print(item.text)
            elif hasattr(item, "blob"):
                print(f"Binary data: {len(item.blob)} bytes")


if __name__ == "__main__":
    asyncio.run(main())
